String encoded = EncodingUtil.urlEncode('A+B trail*', 'US_ASCII');
System.assertEquals('A%2BB+trail*', encoded);
System.assertEquals('A+B trail*', EncodingUtil.urlDecode(encoded, 'ascii'));
System.assertEquals('~', EncodingUtil.urlDecode('%7E', ' us-ascii '));

